1	import { useMemo } from 'react';
2	import { useMiaActions } from '@/hooks/useMiaActions';
3	import type { MiaActionHandler } from '@/types/mia';
4	
5	export interface VendasMiaInterface {
6	  setSearchTerm: (v: string) => void;
7	  setSelectedCategory: (v: string) => void;
8	  setActiveTab: (v: string) => void;
9	  setViewMode: (v: any) => void;
10	  setSelectedStore: (v: any) => void;
11	  setTargetWeekday: (v: string) => void;
12	  setDateRange: (v: any) => void;
13	  setSelectedProductForAnalysis: (v: any) => void;
14	  handleExport: () => void;
15	  analyzedData: any[];
16	}
17	
18	export function useMiaVendasActions(iface: VendasMiaInterface): void {
19	  const {
20	    setSearchTerm,
21	    setSelectedCategory,
22	    setActiveTab,
23	    setViewMode,
24	    setSelectedStore,
25	    setTargetWeekday,
26	    setDateRange,
27	    setSelectedProductForAnalysis,
28	    handleExport,
29	    analyzedData,
30	  } = iface;
31	
32	  const handlers = useMemo<Record<string, MiaActionHandler>>(() => ({
33	    // ── Filter vendas ──
34	    vendas_filter: {
35	      id: 'vendas_filter',
36	      description: 'Filtrar dados de vendas por busca, categoria, loja e dia da semana',
37	      execute: (data) => {
38	        if (!data) return;
39	        if (data.search !== undefined) setSearchTerm(data.search);
40	        if (data.category !== undefined) setSelectedCategory(data.category);
41	        if (data.store !== undefined) setSelectedStore(data.store);
42	        if (data.weekday !== undefined) setTargetWeekday(data.weekday);
43	      },
44	    },
45	
46	    // ── Select tab ──
47	    vendas_select_tab: {
48	      id: 'vendas_select_tab',
49	      description: 'Selecionar aba de vendas (explorar/analytics/producao)',
50	      execute: (data) => {
51	        if (data?.tab) setActiveTab(data.tab);
52	      },
53	    },
54	
55	    // ── Switch view mode ──
56	    vendas_switch_view: {
57	      id: 'vendas_switch_view',
58	      description: 'Trocar modo de visualizacao de vendas (list/table)',
59	      execute: (data) => {
60	        if (data?.view) setViewMode(data.view);
61	      },
62	    },
63	
64	    // ── Date range ──
65	    vendas_date_range: {
66	      id: 'vendas_date_range',
67	      description: 'Definir periodo de datas para analise de vendas',
68	      execute: (data) => {
69	        if (!data) return;
70	        if (data.preset) {
71	          const days = data.preset === '7d' ? 7 : data.preset === '30d' ? 30 : 90;
72	          const now = new Date();
73	          const from = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);
74	          setDateRange({ from, to: now });
75	        } else if (data.from || data.to) {
76	          setDateRange({
77	            from: data.from ? new Date(data.from) : undefined,
78	            to: data.to ? new Date(data.to) : undefined,
79	          });
80	        }
81	      },
82	    },
83	
84	    // ── Open product analysis ──
85	    vendas_open_product: {
86	      id: 'vendas_open_product',
87	      description: 'Abrir analise detalhada de um produto de vendas',
88	      execute: (data) => {
89	        if (!data) return;
90	        let found = null;
91	        if (data.product_name) {
92	          found = analyzedData.find((p: any) =>
93	            p.name?.toLowerCase().includes(data.product_name.toLowerCase())
94	          );
95	        }
96	        if (!found && data.code) {
97	          found = analyzedData.find((p: any) =>
98	            p.code?.toLowerCase().includes(data.code.toLowerCase())
99	          );
100	        }
101	        if (found) setSelectedProductForAnalysis(found);
102	      },
103	    },
104	
105	    // ── Export ──
106	    vendas_export: {
107	      id: 'vendas_export',
108	      description: 'Exportar relatorio de vendas para Excel',
109	      execute: () => {
110	        handleExport();
111	      },
112	    },
113	
114	    // ── Clear filters ──
115	    clear_filters: {
116	      id: 'clear_filters',
117	      description: 'Limpar filtros de vendas',
118	      execute: () => {
119	        setSearchTerm('');
120	        setSelectedCategory('Todas');
121	      },
122	    },
123	  }), [
124	    setSearchTerm,
125	    setSelectedCategory,
126	    setActiveTab,
127	    setViewMode,
128	    setSelectedStore,
129	    setTargetWeekday,
130	    setDateRange,
131	    setSelectedProductForAnalysis,
132	    handleExport,
133	    analyzedData,
134	  ]);
135	
136	  useMiaActions('/vendas', handlers);
137	}
